// ===== ChemE concept glossary (overlay arrives in v2) =====
const CHEME = {
  fermentation:["Fermentation","Microbes turn sugars into acids and CO₂. The batter is a small bioreactor; temperature sets the rate."],
  maillard:["Maillard reaction","Amino acids and reducing sugars react above ~140 °C to form browned, roasted flavour compounds."],
  caramelization:["Caramelization","Sugar breaks down (pyrolysis) above ~160 °C into brown, bitter-sweet compounds."],
  gelatinization:["Starch gelatinization","Starch granules absorb water and swell at 60–80 °C, thickening the liquid; on cooling they retrograde and set."],
  leavening:["Leavening","Gas (CO₂ or steam) inflates a stretchy matrix; the structure must set before the gas escapes."],
  emulsion:["Emulsion","Fat dispersed in water. Stability depends on emulsifiers, temperature and shear; broken on purpose in some gravies."],
  denaturation:["Protein denaturation","Heat, acid or salt unfold proteins so they set, firm up or curdle."],
  enzyme:["Enzyme kinetics","Biological catalysts (papain, amylase) work faster when warm, until heat destroys them."],
  diffusion:["Diffusion and osmosis","Salt, acid and sugar move into food slowly; penetration depth grows with the square root of time."],
  heat:["Heat transfer","Conduction, convection, radiation and the latent heat of condensing steam move energy into food."],
  extraction:["Fat extraction (tadka)","Hot fat dissolves fat-soluble aroma and pigment molecules out of spices."],
  crystallization:["Crystallization","Sugar concentration and cooling rate set crystal size, and so texture."],
  acidbase:["Acid–base chemistry","pH drives leavening, curdling, colour and texture."],
  smoking:["Smoking","Wood pyrolysis vapours (phenols) deposit flavour and slow microbial growth."],
  pressure:["Pressure and boiling point","At about 1 bar above atmospheric, water boils near 120 °C, so a pressure cooker cooks pulses far faster."],
  crosslinking:["Ionic cross-linking","Divalent ions such as Ca²⁺ bridge pectin chains, so cell walls stay firm through cooking."],
  phase:["Phase change","Evaporation, the Leidenfrost effect and boiling-point elevation in syrups all show up at the stove."]
};

